const legacyNodeSources = new WeakMap<Text, string>();
let legacyTranslationInProgress = false;
let legacyTranslationScheduled = false;
function scheduleLegacyUiTranslations(language: Language) {
  if (legacyTranslationScheduled || typeof window === "undefined") return;
  legacyTranslationScheduled = true;
  window.requestAnimationFrame(() => {
    legacyTranslationScheduled = false;
    applyLegacyUiTranslations(language);
  });
}
function applyLegacyUiTranslations(language: Language) {
  if (typeof document === "undefined" || legacyTranslationInProgress) return;
  legacyTranslationInProgress = true;
  const dictionary = language === "ar" ? null : legacyUiTranslations[language];
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let node: Node | null;
  while ((node = walker.nextNode())) {
    const textNode = node as Text;
    if (!legacyNodeSources.has(textNode)) legacyNodeSources.set(textNode, textNode.nodeValue ?? "");
    const source = legacyNodeSources.get(textNode) ?? "";
    const trimmed = source.trim();
    if (!trimmed) continue;
    const translated = dictionary?.[trimmed] ?? (dictionary ? source : source);
    if (translated !== source) textNode.nodeValue = source.replace(trimmed, translated);
    else if (!dictionary) textNode.nodeValue = source;
  }
  try {
    for (const element of Array.from(document.querySelectorAll<HTMLElement>("input, textarea, [aria-label], [title]"))) {
      for (const attribute of ["placeholder", "aria-label", "title"] as const) {
        const source = element.getAttribute(attribute);
        if (!source) continue;
        const translated = dictionary?.[source.trim()];
        if (translated) element.setAttribute(attribute, translated);
        else if (!dictionary && legacyUiTranslations.en[source]) element.setAttribute(attribute, source);
      }
    }
  } finally {
    legacyTranslationInProgress = false;
  }
}

export const translations = { ar: arabic, en: english, fr: french } as const;
export type TranslationKey = keyof typeof arabic;
type LanguageContextValue = { language: Language; direction: "rtl" | "ltr"; locale: string; setLanguage: (language: Language) => void; t: (key: TranslationKey) => string; formatDate: (value: Date | string | number) => string; formatNumber: (value: number) => string };
const LanguageContext = createContext<LanguageContextValue | undefined>(undefined);

function readStoredLanguage(): Language { if (typeof window === "undefined") return "ar"; const stored = window.localStorage.getItem(LANGUAGE_STORAGE_KEY); return stored === "en" || stored === "fr" ? stored : "ar"; }

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguageState] = useState<Language>(readStoredLanguage);
  const meta = languageMeta[language];
  useEffect(() => {
    document.documentElement.lang = language;
    document.documentElement.dir = meta.dir;
    document.body.dir = meta.dir;
    document.body.dataset.language = language;
    window.localStorage.setItem(LANGUAGE_STORAGE_KEY, language);
    applyLegacyUiTranslations(language);
    const observer = new MutationObserver(() => scheduleLegacyUiTranslations(language));
    observer.observe(document.body, { subtree: true, childList: true });
    const refresh = window.setTimeout(() => scheduleLegacyUiTranslations(language), 120);
    return () => { window.clearTimeout(refresh); observer.disconnect(); };
  }, [language, meta.dir]);
  const value = useMemo<LanguageContextValue>(() => ({ language, direction: meta.dir, locale: meta.locale, setLanguage: setLanguageState, t: (key) => translations[language][key], formatDate: (input) => new Intl.DateTimeFormat(meta.locale, { dateStyle: "medium" }).format(new Date(input)), formatNumber: (input) => new Intl.NumberFormat(meta.locale).format(input) }), [language, meta.dir, meta.locale]);
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() { const context = useContext(LanguageContext); if (!context) throw new Error("useLanguage must be used within LanguageProvider"); return context; }
